        if not os.path.exists(path):
            status = "validation_error"
            err_out = _err("NOT_FOUND", "Iris dataset is unavailable.")
        else:
            data = {f: [] for f in numeric_fields}
            with open(path, newline="", encoding="utf-8") as f:
                reader = csv.DictReader(f, delimiter="|")
                if not reader.fieldnames:
                    status = "validation_error"
                    err_out = _err("VALIDATION_ERROR", "Iris dataset header is missing or unreadable.")
                else:
                    missing = [c for c in (numeric_fields + ["species"]) if c not in reader.fieldnames]
                    if missing:
                        status = "validation_error"
                        err_out = _err("VALIDATION_ERROR", "Iris dataset is missing required fields.", missing_fields=missing)
                    else:
                        i = 0
                        for row in reader:
                            i += 1
                            for field in numeric_fields:
                                v = row.get(field)
                                if v is None or str(v).strip() == "":
                                    status = "validation_error"
                                    err_out = _err("VALIDATION_ERROR", "Iris dataset contains missing numeric values.", row_number=i, field=field)
                                    break
                                try:
                                    data[field].append(float(v))
                                except ValueError:
                                    status = "validation_error"
                                    err_out = _err("VALIDATION_ERROR", "Iris dataset contains non-numeric values in numeric columns.", row_number=i, field=field)
                                    break
                            if err_out is not None:
                                break

                        if err_out is None:
                            total_rows = len(data[numeric_fields[0]])
                            if total_rows == 0:
                                status = "validation_error"
                                err_out = _err("VALIDATION_ERROR", "Iris dataset is empty; summary statistics cannot be computed.")
                            else:
                                # compute stats
                                out = {}
