                                    if len(vals) != total_rows:
                                        status = "validation_error"
                                        err_out = _err("VALIDATION_ERROR", "Iris dataset contains inconsistent numeric columns.", field=field)
                                        break
                                    out[field] = {
                                        "count": len(vals),
                                        "mean": sum(vals) / len(vals),
                                        "min": min(vals),
                                        "max": max(vals),
                                    }
                                if err_out is None:
                                    summary_out = out
    except (OSError, csv.Error):
        status = "validation_error"
        err_out = _err("VALIDATION_ERROR", "Iris dataset cannot be loaded or parsed.")

