                        "product": ["product", "product_name"],
                        "city": ["city", "customer_city"],
                        "price": ["price"],
                        "quantity": ["quantity"],
                    }
                    missing_groups = []
                    for group, candidates in required_any.items():
                        if not any(c in reader.fieldnames for c in candidates):
                            missing_groups.append({"field_group": group, "candidates": candidates})
                    if missing_groups:
                        status = "validation_error"
                        err_out = _err("VALIDATION_ERROR", "Sales dataset is missing required fields.", missing=missing_groups)
                    else:
                        out = []
                        i = 0
                        for row in reader:
                            i += 1
                            product = row.get("product", None)
                            if product is None or str(product).strip() == "":
                                product = row.get("product_name", None)
                            city = row.get("city", None)
                            if city is None or str(city).strip() == "":
                                city = row.get("customer_city", None)
                            price = row.get("price", None)
                            quantity = row.get("quantity", None)

                            if product is None or str(product).strip() == "" or city is None or str(city).strip() == "" or price is None or str(price).strip() == "" or quantity is None or str(quantity).strip() == "":
                                status = "validation_error"
                                err_out = _err("VALIDATION_ERROR", "Sales dataset contains missing required fields.", row_number=i)
                                break
                            try:
                                price_f = float(price)
                                qty_f = float(quantity)
                            except ValueError:
                                status = "validation_error"
                                err_out = _err("VALIDATION_ERROR", "Sales dataset contains non-numeric price or quantity.", row_number=i)
                                break

                            rec = dict(row)
                            rec["product"] = str(product)
                            rec["city"] = str(city)
                            rec["price"] = price_f
                            # keep quantity numeric; allow fractional
                            rec["quantity"] = qty_f
                            out.append(rec)
                        if err_out is None:
                            out_rows = out
    except (OSError, csv.Error):
