def aggregate_sales_by_product(**_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0201000" if __import__("os").path.isdir("./environment_mix/0201000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, csv
    from collections import defaultdict

    start = time.time()
    status = "ok"
    err_out = None
    out = None

    try:
        path = os.path.join(_DB, "sales.csv")
        if not os.path.exists(path):
            status = "validation_error"
            err_out = _err("NOT_FOUND", "Sales dataset is unavailable.")
        else:
            with open(path, newline="", encoding="utf-8") as f:
                reader = csv.DictReader(f, delimiter="|")
                if not reader.fieldnames:
                    status = "validation_error"
                    err_out = _err("VALIDATION_ERROR", "Sales dataset header is missing or unreadable.")
                else:
                    # required fields
                    product_field = "product" if "product" in reader.fieldnames else ("product_name" if "product_name" in reader.fieldnames else None)
                    if product_field is None or "price" not in reader.fieldnames or "quantity" not in reader.fieldnames:
                        status = "validation_error"
                        err_out = _err(
                            "VALIDATION_ERROR",
                            "Sales dataset is missing required fields (product, price, quantity).",
                            missing_fields=[x for x in ["product/product_name", "price", "quantity"]
                                            if (x != "product/product_name" and x.replace("/", "") not in reader.fieldnames)
                                            or (x == "product/product_name" and product_field is None)]
                        )
                    else:
                        totals = defaultdict(float)
                        valid_tx = 0
                        i = 0
                        for row in reader:
                            i += 1
                            prod = row.get(product_field)
                            price = row.get("price")
                            qty = row.get("quantity")
                            if prod is None or str(prod).strip() == "" or price is None or str(price).strip() == "" or qty is None or str(qty).strip() == "":
                                continue
                            try:
                                price_f = float(price)
                                qty_f = float(qty)
                            except ValueError:
                                status = "validation_error"
                                err_out = _err("VALIDATION_ERROR", "price/quantity must be numeric to compute revenue.", row_number=i)
                                break
                            totals[str(prod)] += price_f * qty_f
                            valid_tx += 1

                        if err_out is None:
                            if valid_tx == 0:
                                status = "validation_error"
                                err_out = _err("VALIDATION_ERROR", "There are no valid transactions to aggregate.")
                            else:
                                out = [{"product": k, "total_revenue": v} for k, v in totals.items()]
                                out.sort(key=lambda r: (-r["total_revenue"], r["product"]))
    except (OSError, csv.Error):
        status = "validation_error"
        err_out = _err("VALIDATION_ERROR", "Sales dataset cannot be loaded or parsed.")

    # audit/log (best-effort)
    try:
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "aggregate_sales_by_product",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "status": status,
            "latency_ms": int((time.time() - start) * 1000),
        })
        _save("request_log.json", logs)
    except Exception:
        pass

    if err_out is not None:
        return err_out
    return {"data": out, "meta": {"total": len(out)}}

