            if nm is None or not isinstance(nm, str) or nm.strip() == "":
                continue
            names.append(nm)
        if err_out is None:
            if len(names) == 0:
                status = "validation_error"
                err_out = _err("VALIDATION_ERROR", "Dataset is empty or contains no valid country names to return.")
            else:
                out = names

    # audit/log (best-effort)
    try:
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "list_country_names",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "status": status,
            "latency_ms": int((time.time() - start) * 1000),
        })
        _save("request_log.json", logs)
    except Exception:
        pass

    if err_out is not None:
        return err_out
    return {"data": out, "meta": {"total": len(out)}}

def find_country_by_dial_code(dial_code, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0201000" if __import__("os").path.isdir("./environment_mix/0201000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, re

    start = time.time()
    status = "ok"
    err_out = None
    out = None

    if not isinstance(dial_code, str):
        status = "validation_error"
        err_out = _err("VALIDATION_ERROR", "dial_code must be a string.")
    else:
        dc = dial_code.strip()
        if dc == "":
            status = "validation_error"
            err_out = _err("VALIDATION_ERROR", "dial_code must not be empty.")
        elif not re.fullmatch(r"\+\d{1,4}([ -]?\d{1,4})*", dc):
            status = "validation_error"
            err_out = _err("VALIDATION_ERROR", "dial_code must be in dial-code form including the leading '+'.")
        else:
            data = _load("countries.json")
            if not isinstance(data, list):
                status = "validation_error"
                err_out = _err("VALIDATION_ERROR", "Countries dataset cannot be loaded.")
            else:
                res = []
                for c in data:
                    if not isinstance(c, dict):
                        continue
                    v = c.get("dial_code")
                    if isinstance(v, str) and v.strip() == dc:
                        res.append(c)
                out = res

    # audit/log (best-effort)
    try:
        logs = _load("request_log.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "find_country_by_dial_code",
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "status": status,
            "latency_ms": int((time.time() - start) * 1000),
        })
        _save("request_log.json", logs)
    except Exception:
        pass

    if err_out is not None:
        return err_out
    return {"data": out, "meta": {"total": len(out)}}
